    local function VM_O11Oll1l(d, k, m)
        local R_OI00IOl = {}
        local c_key = k
        local char = string.char
        local insert = table.insert
        
        -- Virtual Machine Loop
        for idx = 1, #d do
            local val = d[idx]
            -- Decodificacao Rolling Key
            local dec = (val / m) - c_key
            
            -- Anti-Crash Mobile (Garante byte valido)
            dec = dec % 256
            
            insert(R_OI00IOl, char(dec))
            
            -- Atualiza a chave para o proximo (Rolling)
            c_key = (c_key + 13) % 150
        end
        return table.concat(R_OI00IOl)
    end

    -- Execution Guard
    local F_11II1 = loadstring(VM_O11Oll1l(B_1I0O1I1, 47, 5))
    if F_11II1 then
